CREATE TABLE public.bani_accounting_settings (tenant_id uuid PRIMARY KEY REFERENCES public.tenants(id), enabled boolean NOT NULL DEFAULT true, ask_above numeric CHECK(ask_above IS NULL OR ask_above>=0), paused_reason text, paused_kind text, lease_id uuid, lease_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bani_accounting_settings TO authenticated; GRANT ALL ON public.bani_accounting_settings TO service_role;
ALTER TABLE public.bani_accounting_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bani_accounting_settings_read ON public.bani_accounting_settings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE TABLE public.bani_accounting_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), source_type text NOT NULL CHECK(source_type IN ('expense_bill','invoice','bank_transaction')), source_id uuid NOT NULL, source_date date, label text NOT NULL DEFAULT '', amount numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','checking','asked','posted','reversed','resolved')), reasons jsonb NOT NULL DEFAULT '[]', posting_reason text, document_path text, record_link text NOT NULL DEFAULT '/finance', journal_entry_id uuid, reversal_entry_id uuid, source_fingerprint text, requested_by uuid, checked_at timestamptz, posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,source_type,source_id));
GRANT SELECT ON public.bani_accounting_reviews TO authenticated; GRANT ALL ON public.bani_accounting_reviews TO service_role;
ALTER TABLE public.bani_accounting_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY bani_accounting_reviews_read ON public.bani_accounting_reviews FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')));
CREATE INDEX bani_accounting_reviews_queue ON public.bani_accounting_reviews(tenant_id,status,created_at);
CREATE TABLE public.bani_accounting_examples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),source_type text NOT NULL CHECK(source_type IN ('expense_line','invoice_line','bank_match','supplier_merge','reversal','answer')),source_id uuid NOT NULL, supplier_id uuid,item_key text NOT NULL DEFAULT '',venue text,field text NOT NULL,before_value jsonb NOT NULL DEFAULT '{}',after_value jsonb NOT NULL DEFAULT '{}',reason text,actor_id uuid,conflict_with uuid, resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bani_accounting_examples TO authenticated; GRANT ALL ON public.bani_accounting_examples TO service_role;
ALTER TABLE public.bani_accounting_examples ENABLE ROW LEVEL SECURITY;
CREATE POLICY bani_accounting_examples_read ON public.bani_accounting_examples FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')));
CREATE INDEX bani_accounting_examples_context ON public.bani_accounting_examples(tenant_id,supplier_id,item_key,created_at DESC);
CREATE OR REPLACE FUNCTION public.bani_accounting_save_settings(p_tenant uuid,p_enabled boolean,p_ask_above numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT (public.is_tenant_admin(p_tenant,auth.uid()) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Accounting administrator required'; END IF;
IF p_ask_above<0 THEN RAISE EXCEPTION 'Amount must be zero or more'; END IF;
INSERT INTO public.bani_accounting_settings(tenant_id,enabled,ask_above) VALUES(p_tenant,p_enabled,p_ask_above) ON CONFLICT(tenant_id) DO UPDATE SET enabled=excluded.enabled,ask_above=excluded.ask_above,updated_at=now();
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,details) VALUES(p_tenant,auth.uid(),'bani_accounting_settings','bani_accounting_settings',jsonb_build_object('enabled',p_enabled,'ask_above',p_ask_above)); END $$;
REVOKE ALL ON FUNCTION public.bani_accounting_save_settings(uuid,boolean,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bani_accounting_save_settings(uuid,boolean,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.bani_accounting_enqueue() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text; sid uuid; tid uuid; st text; d date; l text; a numeric; link text; BEGIN
IF TG_TABLE_NAME='expense_bill_allocations' THEN SELECT tenant_id,approval_status,bill_date,vendor_name,total_amount INTO tid,st,d,l,a FROM public.expense_bills WHERE id=coalesce(NEW.bill_id,OLD.bill_id); sid:=coalesce(NEW.bill_id,OLD.bill_id);typ:='expense_bill';link:='/expenses?bill='||sid;
ELSIF TG_TABLE_NAME='invoice_line_items' THEN SELECT tenant_id,review_status,invoice_date,invoice_number,total_amount INTO tid,st,d,l,a FROM public.invoices WHERE id=coalesce(NEW.invoice_id,OLD.invoice_id);sid:=coalesce(NEW.invoice_id,OLD.invoice_id);typ:='invoice';link:='/procurement/invoices?invoice='||sid;
ELSIF TG_TABLE_NAME='goods_received_notes' THEN SELECT tenant_id,review_status,invoice_date,invoice_number,total_amount INTO tid,st,d,l,a FROM public.invoices WHERE id=NEW.invoice_id;sid:=NEW.invoice_id;typ:='invoice';link:='/procurement/invoices?invoice='||sid;
ELSIF TG_TABLE_NAME='expense_bills' THEN tid:=NEW.tenant_id;sid:=NEW.id;st:=NEW.approval_status;d:=NEW.bill_date;l:=NEW.vendor_name;a:=NEW.total_amount;typ:='expense_bill';link:='/expenses?bill='||sid;
ELSIF TG_TABLE_NAME='invoices' THEN tid:=NEW.tenant_id;sid:=NEW.id;st:=NEW.review_status;d:=NEW.invoice_date;l:=NEW.invoice_number;a:=NEW.total_amount;typ:='invoice';link:='/procurement/invoices?invoice='||sid;
ELSE tid:=NEW.tenant_id;sid:=NEW.id;st:=NEW.status;d:=NEW.txn_date;l:=NEW.description;a:=greatest(NEW.money_in,NEW.money_out);typ:='bank_transaction';link:='/bank/reconciliation'; END IF;
IF tid IS NULL OR sid IS NULL THEN RETURN NEW; END IF;
IF (typ='expense_bill' AND st IN ('posted','reversed','void','rejected')) OR (typ='invoice' AND st IN ('Approved','Disputed','Voided')) OR (typ='bank_transaction' AND st NOT IN ('unmatched','pending')) THEN
UPDATE public.bani_accounting_reviews SET status='resolved',updated_at=now() WHERE tenant_id=tid AND source_type=typ AND source_id=sid AND status IN ('queued','asked'); RETURN NEW; END IF;
INSERT INTO public.bani_accounting_reviews(tenant_id,source_type,source_id,source_date,label,amount,record_link,requested_by) VALUES(tid,typ,sid,d,coalesce(l,''),coalesce(a,0),link,auth.uid()) ON CONFLICT(tenant_id,source_type,source_id) DO UPDATE SET status=CASE WHEN bani_accounting_reviews.status IN ('posted','reversed','checking') THEN bani_accounting_reviews.status ELSE 'queued' END,source_date=d,label=coalesce(l,''),amount=coalesce(a,0),updated_at=now();RETURN NEW;END $$;
CREATE TRIGGER bani_queue_bill AFTER INSERT OR UPDATE ON public.expense_bills FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE TRIGGER bani_queue_allocation AFTER INSERT OR UPDATE OR DELETE ON public.expense_bill_allocations FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE TRIGGER bani_queue_invoice AFTER INSERT OR UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE TRIGGER bani_queue_invoice_line AFTER INSERT OR UPDATE OR DELETE ON public.invoice_line_items FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE TRIGGER bani_queue_delivery AFTER INSERT OR UPDATE ON public.goods_received_notes FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE TRIGGER bani_queue_bank AFTER INSERT OR UPDATE ON public.bank_transactions FOR EACH ROW EXECUTE FUNCTION public.bani_accounting_enqueue();
CREATE OR REPLACE FUNCTION public.bani_accounting_lease(p_tenant uuid,p_lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.bani_accounting_settings(tenant_id) VALUES(p_tenant) ON CONFLICT DO NOTHING;
UPDATE public.bani_accounting_settings SET lease_id=p_lease,lease_until=now()+interval '10 minutes' WHERE tenant_id=p_tenant AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.bani_accounting_lease(uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.bani_accounting_lease(uuid,uuid) TO service_role;